def _decode(text):
    return unquote(text.replace("+", " "))


def parse_query(qs):
    qs = qs[1:] if qs[:1] == "?" else qs
    result = {}
    for pair in qs.split("&"):
        if pair == "":
            continue
        parts = pair.split("=", 1)
        value = parts[1] if len(parts) > 1 else ""
        result[_decode(parts[0])] = _decode(value)
    return result

from urllib.parse import unquote_plus


def _pairs(text):
    for chunk in text.split("&"):
        if chunk:
            name, _, val = chunk.partition("=")
            yield unquote_plus(name), unquote_plus(val)


def parse_query(qs):
    if qs.startswith("?"):
        qs = qs[1:]
    out = {}
    out.update(_pairs(qs))
    return out

