def pick_port(used, low, high):
    free = set(range(low, high + 1)) - set(used)
    if not free:
        return None
    return min(free)

def pick_port(used, low, high):
    candidate = low
    while candidate <= high:
        if candidate not in used:
            return candidate
        candidate += 1
