def luhn_valid(number):
    digits = "".join(ch for ch in number if ch not in " -")
    if len(digits) < 12 or len(digits) > 19:
        return False
    if not all("0" <= ch <= "9" for ch in digits):
        return False
    values = [int(ch) for ch in reversed(digits)]
    doubled = [0, 2, 4, 6, 8, 1, 3, 5, 7, 9]
    total = sum(values[0::2]) + sum(doubled[v] for v in values[1::2])
